static String mcastMac(InetAddress a) {
  byte[] b = a.getAddress();
  if (!a.isMulticastAddress()) throw new IllegalArgumentException();
  return a instanceof Inet4Address
    ? String.format("01:00:5e:%02x:%02x:%02x", b[1] & 0x7f, b[2] & 0xff, b[3] & 0xff)
    : String.format("33:33:%02x:%02x:%02x:%02x", b[12] & 0xff, b[13] & 0xff, b[14] & 0xff, b[15] & 0xff);
}
